        return;
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const { title, images, variants } = parseShopifyData(content);

    if (!title || variants.length === 0) {
        console.error('Lỗi: Không parse được tiêu đề hoặc biến thể của sản phẩm!');
        return;
