    // Xác định danh mục sản phẩm (category_id)
    // 31: Áo Nữ (category_id = 7)
    // 34: Quần Nữ (category_id = 8)
    // 37: Áo Khoác Nữ (category_id = 9)
    let categoryId = 7; // mặc định Áo Nữ
    if (productId === 34) categoryId = 8;
    else if (productId === 37) categoryId = 9;

    // 2. Cập nhật bảng products
    await db.query(`
        UPDATE products 
        SET name = ?, price = ?, price_sale = NULL, image = ?, description = ?, category_id = ?, brand_id = 1
        WHERE id = ?
    `, [title, price, mainProductImage, desc, categoryId, productId]);
    console.log(`Đã cập nhật thông tin sản phẩm chính trong DB.`);

